</fieldset>
<div class="d-flex flex-column gap-0  event-registration-form mt-5">
<h4 style="padding-bottom: 0px; margin-bottom:0px;">Parent''s Details</h4>
<div class="row mb-0">
<div class="col-12 mt-0">
