</figure>
</div>



<div class="wp-block-column is-layout-flow wp-block-column-is-layout-flow">
<figure class="wp-block-gallery has-nested-images columns-default is-cropped wp-block-gallery-21 is-layout-flex wp-block-gallery-is-layout-flex">
<figure class="wp-block-image size-full"><img loading="lazy" decoding="async" width="1024" height="730" data-id="137" src="https://kja.ug/wp-content/uploads/2025/08/1748603419425-1741764450239-1719396566378-3f887179-0fa2-478d-8784-44c725fd6962.png" alt="" class="wp-image-137"/></figure>
</figure>
</div>
