insert into public.news (slug, title, excerpt, body, image_url, author, published_at, seo_description) values
  ('kja-celebrates-excellent-2025-ple-results', 'KJA Celebrates Excellent 2025 PLE Results', 'At Kampala Junior Academy, we are delighted to officially share our 2025 Primary Leaving Examination (PLE) results with our parents, guardians, and the wider community. This year, 131 candidates sat [&hellip;]', '<div style="height:23px" aria-hidden="true" class="wp-block-spacer"></div>



<p class="wp-block-paragraph">At <strong>Kampala Junior Academy</strong>, we are delighted to officially share our 2025 Primary Leaving Examination (PLE) results with our parents, guardians, and the wider community.</p>



<p class="wp-block-paragraph">This year, <strong>131 candidates</strong> sat for the PLE, and we are proud to report an outstanding performance:</p>



<ul class="wp-block-list">
<li><strong>97 pupils (74%)</strong> achieved Division I</li>



<li><strong>34 pupils (26%)</strong> achieved Division II</li>



<li><strong>0 pupils</strong> in Division III & IV</li>
</ul>



<p class="wp-block-paragraph">We celebrate a <strong>100% pass rate in Division I and II</strong>, a clear testimony of the hard work, discipline, and resilience of our learners.</p>



<div style="height:27px" aria-hidden="true" class="wp-block-spacer"></div>



<h3 class="wp-block-heading">Strong Aggregate Performance</h3>



<div style="height:16px" aria-hidden="true" class="wp-block-spacer"></div>



<p class="wp-block-paragraph">Our aggregate distribution reflects consistency and academic strength across the class:</p>



<ul class="wp-block-list">
<li>3 pupils scored <strong>Aggregate 4</strong></li>



<li>13 pupils scored <strong>Aggregate 5</strong></li>



<li>11 pupils scored <strong>Aggregate 6</strong></li>



<li>11 pupils scored <strong>Aggregate 7</strong></li>



<li>16 pupils scored <strong>Aggregate 8</strong></li>



<li>20 pupils scored <strong>Aggregate 9</strong></li>
</ul>



<p class="wp-block-paragraph">The majority of our candidates scored within the strongest aggregate groups, with very few pupils in the higher aggregate ranges. </p>



<div style="height:35px" aria-hidden="true" class="wp-block-spacer"></div>



<h3 class="wp-block-heading">A Testament to Teamwork</h3>



<div style="height:23px" aria-hidden="true" class="wp-block-spacer"></div>



<p class="wp-block-paragraph">These results are not by chance. They are the outcome of:</p>



<ul class="wp-block-list">
<li>Dedicated and experienced teachers</li>



<li>Supportive and cooperative parents</li>



<li>A structured academic programme</li>



<li>Continuous assessment and remedial support</li>



<li>Above all, disciplined and determined pupils</li>
</ul>



<p class="wp-block-paragraph">As a school, we believe that excellence is built through consistency, guidance, and strong moral values. We are grateful to God for seeing our candidates through this important milestone.</p>



<div style="height:25px" aria-hidden="true" class="wp-block-spacer"></div>



<h3 class="wp-block-heading">Looking Ahead</h3>



<div style="height:21px" aria-hidden="true" class="wp-block-spacer"></div>



<p class="wp-block-paragraph">We congratulate our Primary Seven class of 2025 for making the school proud. As they transition to secondary school, we are confident that they will continue to uphold the values of hard work, integrity, and leadership instilled in them at Kampala Junior Academy.</p>



<p class="wp-block-paragraph">To our parents and stakeholders, thank you for trusting us with your children. Together, we continue to nurture future leaders for Uganda and beyond.</p>



<p class="wp-block-paragraph"><strong>Congratulations to the Class of 2025!</strong> </p>', 'https://kja.ug/wp-content/uploads/2026/02/PLE-results.png', 'Mukisa-KJA', '2026-02-23T07:00:00', 'At Kampala Junior Academy, we are delighted to officially share our 2025 Primary Leaving Examination (PLE) results with our parents, guardians, and the wider community. This year, 131 candidates sat [&hellip;]'),
  ('primary-one-and-two-trip', 'Primary one and two Trip', 'Kitante Students of primary one and two had a trip to Bweya Airstrip along Entebbe road in Kajjansi. They met guides who taught them the history of the place and [&hellip;]', '<p class="wp-block-paragraph" id="block-4de829c0-1374-4e6f-8005-e2d3991220ce">Kitante Students of primary one and two had a trip to Bweya Airstrip along Entebbe road in Kajjansi. They met guides who taught them the history of the place and also got a chance to sit in the aero plane. The students enjoyed and narrated the story to the fellow students who did not go.</p>



<p class="wp-block-paragraph" id="block-ce0e0b11-8385-4962-9518-676261368521"></p>



<p class="wp-block-paragraph" id="block-cb2f2447-62be-4ded-a02a-ae1ab0486f51"></p>', 'https://kja.ug/wp-content/uploads/2025/10/IMG-20251020-WA0152.jpg', 'Mukisa-KJA', '2025-10-23T09:37:44', 'Kitante Students of primary one and two had a trip to Bweya Airstrip along Entebbe road in Kajjansi. They met guides who taught them the history of the place and [&hellip;]');


insert into public.posts (slug, title, excerpt, body, image_url, author, published_at, seo_description) values
  ('natania-an-alumni-is-to-represent-uganda-at-the-international-mathematics-competitions-an-alumni-of-ours', 'Alumni Accomplishments: Making Figures A Symphony', 'When others see numbers, she hears music. A symphony of logic rising beyond the classroom awaits.  Our very own alumni, Okaka Natania. Through chalk-dust battles and midnight theorems she started. [&hellip;]', '<p class="wp-block-paragraph">When others see numbers, she hears music. A symphony of logic rising beyond the classroom awaits. </p>



<div class="wp-block-group is-nowrap is-layout-flex wp-container-core-group-is-layout-7387b849 wp-block-group-is-layout-flex">
<p class="wp-block-paragraph">Our very own alumni, Okaka Natania. Through chalk-dust battles and midnight theorems she started. Representing KJA at intermediate mathematics competitions, she continued beating the odds at every stage until equations bent gently to her will. Today, having joined Gayaza High School, Natania is ready to carry the nation. </p>
</div>



<figure class="wp-block-image alignright size-large is-resized"><img loading="lazy" decoding="async" width="792" height="1024" src="https://kja.ug/wp-content/uploads/2026/04/IMG_6334-scaled-e1776083379158-792x1024.jpeg" alt="" class="wp-image-981" style="aspect-ratio:0.7734491239789877;width:310px;height:auto" srcset="https://kja.ug/wp-content/uploads/2026/04/IMG_6334-scaled-e1776083379158-792x1024.jpeg 792w, https://kja.ug/wp-content/uploads/2026/04/IMG_6334-scaled-e1776083379158-232x300.jpeg 232w, https://kja.ug/wp-content/uploads/2026/04/IMG_6334-scaled-e1776083379158-768x993.jpeg 768w, https://kja.ug/wp-content/uploads/2026/04/IMG_6334-scaled-e1776083379158-1188x1536.jpeg 1188w, https://kja.ug/wp-content/uploads/2026/04/IMG_6334-scaled-e1776083379158-1584x2048.jpeg 1584w, https://kja.ug/wp-content/uploads/2026/04/IMG_6334-scaled-e1776083379158.jpeg 1920w" sizes="auto, (max-width: 792px) 100vw, 792px" /></figure>



<figure class="wp-block-pullquote has-text-align-left"><blockquote><p>Natania is to represent Uganda at the International Mathematics competitions in Ulaanbaatar, Mongolia in 2026. </p></blockquote></figure>



<p class="wp-block-paragraph">A journey of a thousand miles begins with one mathematics contest. </p>



<p class="wp-block-paragraph">We kindly invite our alumni to complete the questionnaire here: <a href="https://kja.ug/alumni-get-in-touch/">Kampala Junior Academy alumni</a></p>



<p class="wp-block-paragraph"></p>', 'https://kja.ug/wp-content/uploads/2026/04/IMG_6333-scaled-e1776083302319.jpeg', 'Mukisa-KJA', '2026-04-13T15:59:43', 'Kampala Junior Academy alumna Okaka Natania from Kampala will represent Uganda at the 2026 International Mathematics Competition in Mongolia. Read her inspiring journey.');


