insert into public.alumni_news (slug, title, excerpt, body, image_url, author, published_at) values
  ('nabbira-geneviev-and-nassozi-gina', 'Nabbira Geneviev and Nassozi Gina.', 'KJA brings you two dedicated mechanical engineers; Nabbira Geneviev and Nassozi Gina.They went through KJA, scoring aggregate 6 and 8 respectively in their PLE’s. The duo is currently doing their [&hellip;]', '<p class="wp-block-paragraph">KJA brings you two dedicated mechanical engineers; Nabbira Geneviev and Nassozi Gina.They went through KJA, scoring aggregate 6 and 8 respectively in their PLE’s. The duo is currently doing their internship at Entebbe International Airport. We are proud of them and wish them successful careers in all their endeavors.</p>



<p class="wp-block-paragraph"></p>', 'https://kja.ug/wp-content/uploads/2025/10/1721029205341Black-Simple-Newspaper-Birthday-Poster-8.png', 'KJA', '2025-10-01T03:05:33');


insert into public.alumni_stories (slug, title, excerpt, body, image_url, author, published_at) values
  ('masembe-ibrahim-class-of-2007', 'Masembe Ibrahim- Class of 2007', null, '<p class="wp-block-paragraph">Reflecting on my time at Kampala Junior Academy, I look back with immense gratitude. The school fostered a strong sense of community, discipline, and healthy competition-particularly in Mathematics, a subject l''ve always been passionate about. My leadership experience as Head Boy in 2007-2008 and the successful completion of my Primary Leaving Examinations marked the beginning of an exciting educational journey. I went on to attend King''s College Budo for my secondary education and later pursued a degree in Software Engineering. Upon graduation, I joined KPMG UK as a Technology Auditor and Tech Risk Consultant, working with clients across banking, automotive, and tech sectors to manage technology-related risks.</p>



<div style="height:45px" aria-hidden="true" class="wp-block-spacer"></div>



<p class="wp-block-paragraph">Today, I serve as a Product Owner in KPMG''s innovation department, leading the development of global software solutions used across the firm. Throughout this journey, I have learned the value of continuous learning, staying true to one''s passions, embracing challenges, and giving back. To current students at Kampala Junior Academy: work hard, dream big, and trust that the strong foundation you are building today will pave the way for future success.</p>



<div style="height:43px" aria-hidden="true" class="wp-block-spacer"></div>



<p class="wp-block-paragraph">Masembe Ibrahim,<br>(Class of 2007)</p>



<p class="wp-block-paragraph"></p>', 'https://kja.ug/wp-content/uploads/2025/09/1749031190449Alumni-Post-web.png', 'KJA', '2025-09-22T00:34:07'),
  ('yannich-garcha-class-of-2011', 'Yannich Garcha- Class of 2011', null, '<p class="wp-block-paragraph">In 2008, my educational journey began at KJA, where I consistently aimed for excellence and found myself among the top achievers. Fast forward to 2013, I graduated and went to SMACK, where I faced the unique experience of boarding school life. The new environment posed challenges, but tackling each hurdle one step at a time made all the difference.</p>



<div style="height:39px" aria-hidden="true" class="wp-block-spacer"></div>



<p class="wp-block-paragraph">Upon completing my O-level journey, I dared to chase my dream of becoming a pilot, all while navigating the demands of A-level studies. Balancing these commitments was not simple, yet my unwavering determination kept me going. I successfully acquired my pilot’s licenses and today, I proudly serve as a commercial pilot at Bar Aviation Uganda. My role involves not only maintaining the highest safety standards but also ensuring top-tier customer- service and safety during charter flights across our nation’s skies.</p>



<div style="height:38px" aria-hidden="true" class="wp-block-spacer"></div>



<p class="wp-block-paragraph">To the students of KJA, I want to convey that success in achieving your goals is born from planning, determination, and incremental progress. Challenges are not roadblocks, but stepping stones to your aspirations. As you maneuver through your academic journey, remember that by embracing difficulties and focusing on one step at a time, you will develop the resilience needed to soar to new heights. Just as my time at KJA laid the foundation for my achievements, let every experience mold you into the person you aspire to be, ready to conquer the skies of possibility.</p>', 'https://kja.ug/wp-content/uploads/2025/09/17249323194415.png', 'KJA', '2024-06-13T00:56:00');


insert into public.alumni_profiles (slug, title, excerpt, body, image_url, role) values
  ('ashley-businge-class-of-2015', 'Ashley Businge, Class of: 2015', 'Bio 5 years The party days and the club memories. Swimming. Athletes It was sad that I had to live my friends because we all went to different schools for [&hellip;]', '<h2 class="wp-block-heading">Bio</h2>



<div style="height:45px" aria-hidden="true" class="wp-block-spacer"></div>



<p class="wp-block-paragraph">5 years</p>



<div style="height:30px" aria-hidden="true" class="wp-block-spacer"></div>



<p class="wp-block-paragraph">The party days and the club memories.</p>



<div style="height:32px" aria-hidden="true" class="wp-block-spacer"></div>



<p class="wp-block-paragraph">Swimming.</p>



<p class="wp-block-paragraph">Athletes</p>



<div style="height:39px" aria-hidden="true" class="wp-block-spacer"></div>



<p class="wp-block-paragraph">It was sad that I had to live my friends because we all went to different schools for high school but it’s normal cause that’s life.</p>



<div style="height:33px" aria-hidden="true" class="wp-block-spacer"></div>



<p class="wp-block-paragraph">Am pursuing bachelor of business administration at Makerere University currently going to 3rd year. I have visited many places so far.</p>



<div style="height:34px" aria-hidden="true" class="wp-block-spacer"></div>



<p class="wp-block-paragraph">To read hard and there is bright future awaiting them all.</p>', 'https://kja.ug/wp-content/uploads/2025/09/Ashley-Businge_1748120871192_5e1e907f-4457-45f8-b768-8badd98c0eb6.jpeg', 'Bio 5 years The party days and the club memories. Swimming. Athletes It was sad that I had to live my friends because we all went to different schools for [&hellip;]');


